/**
 * Go through clusters and send out metrics, so we could show which queues are on which clusters.
 *
 * @param configuration App configuration
 * @param periodicMetrics Metric instances
 */
private void sendQueueInfoMetrics(AppConfig configuration, CounterMetricContainer periodicMetrics) {
    if (configuration.getSparkClusters() != null) {
        for (AppConfig.SparkCluster cluster : configuration.getSparkClusters()) {
            List<String> sparkVersions = cluster.getSparkVersions() == null ? new ArrayList<>() : cluster.getSparkVersions();
            List<String> queues = cluster.getQueues() == null ? new ArrayList<>() : cluster.getQueues();
            for (String sparkVersion : sparkVersions) {
                for (String queue : queues) {
                    periodicMetrics.increment(QUEUE_INFO, Tag.of("eks", cluster.getEksCluster()), Tag.of("spark_cluster_id", cluster.getId()), Tag.of("spark_version", sparkVersion), Tag.of("queue", queue));
                }
            }
        }
    }
}
